CONTRA = (15.5, 'Constata la contraindicación y NO realiza la artrocentesis: informa al paciente, lo deriva para su resolución y lo registra', F3, 'rodilla', 1, {'contra': 1}, 'contraindicado',
  'Hay contraindicaciones relativas que obligan a postergar o derivar: infección activa de la piel o del tejido celular subcutáneo sobre el sitio de punción (celulitis), trastornos graves de la coagulación (RIN mayor de 3 o plaquetas ≤ 30 000/mm³), alergia conocida a los anestésicos locales y prótesis articular (manejo por traumatología). Saber cuándo no punzar es parte de la técnica: se suspende, se explica al paciente, se registra y se deriva. Realizar la punción igual es criterio de desaprobación.',
  [['no realizo la artrocentesis'], ['no hago la artrocentesis'], ['no efectuo'], ['contraindic'], ['suspendo'], ['no corresponde'], ['lo derivo'], ['postergo']], 'Constato una contraindicación: no realizo la artrocentesis, informo al paciente, lo derivo y lo registro.', {'solo_contra': True})
pasos = []
for n, tx, fa, tg, cr, es, fx, ex, cl, fr, extra in P + [CONTRA]:
    p = dict(n=n, texto=tx, fase=fa, target=tg, critico=bool(cr), explica=ex, estado=es, claves=cl, frase=fr, fx=fx); p.update(extra)
    if 15 <= n <= 43 and n != 15.5 and not p.get('solo_si') and not p.get('sin_si'): p['sin_contra'] = True
    if p.get('solo_si') or p.get('sin_si'):
        if 15 <= n <= 43: p['sin_contra'] = True
    pasos.append(p)
pasos.sort(key=lambda q: q['n'])

