def caso(i, nombre, sexo, edad, motivo, ant, orden, anam, pa, expl, liq_txt, liq, grande=False, escaso=False, contra=None, extra=None, deb=None):
    c = dict(id=i, nombre=nombre, sexo=sexo, edad=edad, motivo=motivo, indicacion='Artrocentesis de rodilla derecha.' if not contra else 'Artrocentesis de rodilla derecha (a evaluar).', antecedentes=ant, alergia=None,
             grande=grande, escaso=escaso, extra=extra or [],
             orden=orden, filiat=f'Paciente: {nombre} · DNI coincide con la orden y la historia clínica.', anamnesis=anam, pa_txt=pa, hallazgo=expl, liq_txt=liq_txt, liq=liq,
             debito=deb or 'Al aspirar suavemente aparece líquido en la jeringa: la aguja está dentro de la articulación.',
             tubos_txt='Tubo 1 (sin heparina): Gram y cultivo · Tubo 2 (sin heparina): cristales · Tubo 3 (con heparina): recuento celular · Tubo 4 (con heparina): fisicoquímico.' if not escaso else 'Volumen mínimo útil: 0,5 mL para cultivo (sin heparina) y 1 a 2 mL para recuento celular (con heparina).')
    if contra: c['contra'] = contra
    return c
